NS_IMPL_ISUPPORTS(UrlListener, nsIUrlListener)

NS_IMETHODIMP UrlListener::OnStartRunningUrl(nsIURI* url) {
  if (!mStartFn) {
    return NS_OK;
  }
  return mStartFn(url);
}

NS_IMETHODIMP UrlListener::OnStopRunningUrl(nsIURI* url, nsresult exitCode) {
  if (!mStopFn) {
    return NS_OK;
  }
  return mStopFn(url, exitCode);
}
